/**
 * Parse VCD (Value Change Dump) files generated by Verilog simulators
 * 
 * VCD format reference: IEEE 1364-2001
 * 
 * Example VCD:
 * $timescale 1ns $end
 * $var wire 1 ! clk $end
 * $var wire 1 # rst $end
 * $dumpvars
 * 0!
 * 0#
 * $end
 * #5
 * 1!
 * #10
 * 0!
 */

/**
 * Parse VCD file content into structured signal data
 * @param {string} vcdContent - Raw VCD file content
 * @returns {Object} Parsed VCD data with signals and timing
 */
export function parseVCD(vcdContent) {
  const lines = vcdContent.split('\n').map(line => line.trim()).filter(line => line.length > 0);
  
  const result = {
    timescale: '1ns', // Default
    endtime: 0,
    signals: []
  };

  const symbolMap = new Map(); // Maps VCD symbol (!, #, etc.) to signal object
  let currentTime = 0;
  let inDumpvars = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Parse timescale
    if (line.startsWith('$timescale')) {
      const match = line.match(/\$timescale\s+(\S+)\s+\$end/);
      if (match) {
        result.timescale = match[1];
      }
      continue;
    }

    // Parse variable declarations
    if (line.startsWith('$var')) {
      // $var <type> <width> <symbol> <name> $end
      const match = line.match(/\$var\s+(\w+)\s+(\d+)\s+(\S+)\s+(\S+)(?:\s+\$end)?/);
      if (match) {
        const [, type, width, symbol, name] = match;
        const signal = {
          id: name,
          name: name,
          type: type,
          width: parseInt(width, 10),
          values: []
        };
        result.signals.push(signal);
        symbolMap.set(symbol, signal);
      }
      continue;
    }

    // Start of initial values
    if (line.startsWith('$dumpvars')) {
      inDumpvars = true;
      currentTime = 0;
      continue;
    }

    // End of initial values section
    if (line === '$end' && inDumpvars) {
      inDumpvars = false;
      continue;
    }

    // Time marker: #<time>
    if (line.startsWith('#')) {
      const timeMatch = line.match(/^#(\d+)/);
      if (timeMatch) {
        currentTime = parseInt(timeMatch[1], 10);
        result.endtime = Math.max(result.endtime, currentTime);
      }
      continue;
    }

    // Value change: <value><symbol> or b<binary> <symbol>
    // Examples: "0!", "1#", "b0101 $"
    
    // Scalar value change: 0!, 1#, x!, z!
    const scalarMatch = line.match(/^([01xzXZ])(\S+)$/);
    if (scalarMatch) {
      const [, value, symbol] = scalarMatch;
      const signal = symbolMap.get(symbol);
      if (signal) {
        signal.values.push({
          time: currentTime,
          value: value.toLowerCase()
        });
      }
      continue;
    }

    // Binary/vector value change: b0101 $, b01x1 %
    const vectorMatch = line.match(/^b([01xzXZ]+)\s+(\S+)$/);
    if (vectorMatch) {
      const [, value, symbol] = vectorMatch;
      const signal = symbolMap.get(symbol);
      if (signal) {
        signal.values.push({
          time: currentTime,
          value: value.toLowerCase()
        });
      }
      continue;
    }

    // Real value change: r1.234 $
    const realMatch = line.match(/^r([\d.eE+-]+)\s+(\S+)$/);
    if (realMatch) {
      const [, value, symbol] = realMatch;
      const signal = symbolMap.get(symbol);
      if (signal) {
        signal.values.push({
          time: currentTime,
          value: value
        });
      }
      continue;
    }
  }

  // Sort signal values by time (should already be sorted, but ensure)
  result.signals.forEach(signal => {
    signal.values.sort((a, b) => a.time - b.time);
    
    // Remove duplicate consecutive values at same time
    signal.values = signal.values.filter((val, idx, arr) => {
      if (idx === 0) return true;
      return val.time !== arr[idx - 1].time || val.value !== arr[idx - 1].value;
    });
  });

  return result;
}

/**
 * Validate that a VCD file has the expected format
 * @param {string} vcdContent - Raw VCD content
 * @returns {boolean}
 */
export function isValidVCD(vcdContent) {
  if (!vcdContent || typeof vcdContent !== 'string') {
    return false;
  }

  // VCD must contain at least a $var declaration and some time markers
  const hasVar = vcdContent.includes('$var');
  const hasTime = /#\d+/.test(vcdContent);
  
  return hasVar && hasTime;
}

/**
 * Extract signal names from VCD without full parsing
 * @param {string} vcdContent - Raw VCD content
 * @returns {string[]} Array of signal names
 */
export function extractSignalNames(vcdContent) {
  const names = [];
  const lines = vcdContent.split('\n');
  
  for (const line of lines) {
    const match = line.match(/\$var\s+\w+\s+\d+\s+\S+\s+(\S+)/);
    if (match) {
      names.push(match[1]);
    }
  }
  
  return names;
}

export default parseVCD;
